using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class ClothingScaleAudit{static ClothingScaleAudit(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling||!File.Exists("ClothingScaleAudit.request"))return;File.Delete("ClothingScaleAudit.request");var rs=UnityEngine.Object.FindObjectsOfType<Renderer>(true);var list=rs.Where(r=>r.name.StartsWith("building_a_00_Material #163_0")).Select(r=>r.name+" bounds="+r.bounds+" pos="+r.transform.position+" rotation="+r.transform.eulerAngles+" scale="+r.transform.lossyScale+" mesh="+(r.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh):"none")).ToList();foreach(var c in UnityEngine.Object.FindObjectsOfType<CharacterController>(true))list.Add("PLAYER "+c.name+" height="+c.height+" scale="+c.transform.lossyScale+" worldheight="+(c.height*c.transform.lossyScale.y));foreach(var r in rs.Where(r=>r is SkinnedMeshRenderer&&(r.name.ToLower().Contains("girl")||r.transform.root.name.ToLower().Contains("player"))))list.Add("PLAYER RENDERER "+r.name+" root="+r.transform.root.name+" "+r.bounds);list.Add("SceneView pose="+SceneView.lastActiveSceneView.camera.transform.position+" rotation="+SceneView.lastActiveSceneView.camera.transform.eulerAngles);File.WriteAllLines("FinalEnvironmentRoadReview/ClothingScaleAudit.txt",list);}}
